import random,collections,json

def simulate(seed,mode,p=0.8):
 r=random.Random(seed);book=[]
 for page in range(6):
  for row in range(36):
   latent=r.randrange(2);t=[]
   for j in range(12):
    def draw():return latent if r.random()<p else 1-latent
    a,b=draw(),draw()
    if mode=='independent':a=r.randrange(2);b=r.randrange(2)
    if mode=='markov' and j>=5:a=t[-1][1] if r.random()<.85 else 1-t[-1][1]
    t.append((a,b))
   book.append((page,t))
 return book

def test(book,style,seed):
 # Probe is first four end bits; held-out pairs are 4->5 through 10->11.
 groups=collections.defaultdict(list)
 for row,(page,words) in enumerate(book):
  vote=sum(w[1] for w in words[:4]);proxy=(vote>=2)
  for j in range(4,12):groups[(page,j,proxy if style=='proxy' else 0)].append((row,j))
 def score(b):return sum(b[row][1][j][1]==b[row][1][j+1][0] for row in range(len(b)) for j in range(4,11))
 obs=score(book); sh=[];r=random.Random(seed)
 for k in range(99):
  cand=[(page,list(words)) for page,words in book]
  for indices in groups.values():
   vals=[book[row][1][j] for row,j in indices];r.shuffle(vals)
   for (row,j),v in zip(indices,vals):cand[row][1][j]=v
  sh.append(score(cand))
 movable=sum(len({book[row][1][j] for row,j in indices})>1 for indices in groups.values())
 return (1+sum(x>=obs for x in sh))/100,movable
out={}
for mode,p in [('independent',.8),('latent',.7),('latent',.8),('latent',.9),('latent',1),('markov',.8)]:
 key=f'{mode}_{p}';pvals={style:[test(simulate(i,mode,p),style,10000+i)[0] for i in range(30)] for style in ['base','proxy']}
 out[key]={style:{'rejections_005':sum(x<=.05 for x in vals),'pvalues':vals} for style,vals in pvals.items()}
print(json.dumps(out,indent=2))

